parameters.jsCode:
// Data Normalization Script
const title = $json.title || "Target Prospect";
const website = $json.website || null;

// Extract the first email from the 'emails' array if present
const email = ($json.emails && $json.emails.length > 0) ? $json.emails[0] : null;

const category = $json.categoryName || "Local Business";

return {
  company_name: title,
  website_url: website,
  contact_email: email,
  business_category: category,
  has_email: email !== null, // Helper flag for routing
  processed_at: new Date().toISOString()
};

// Extract primary contacts from Apify array output
const scrapedEmails = $json.emails || [];
const scrapedPhones = $json.phones || [];
const linkedIns = $json.linkedIns || [];
const facebooks = $json.facebooks || [];
const instagrams = $json.instagrams || [];

// Reference clean data from 1st stage
const originalData = $('Data Cleaning & Normalization').item.json;

return {
  // 1. Data for the AI Node (Simple, Clean, Low Tokens)
  company_name: originalData.company_name,
  website_url: originalData.website_url,
  business_category: originalData.business_category,
  contact_email: scrapedEmails[0] || originalData.contact_email || null,

  // 2. Data for Google Sheets / CRM (Multi-Channel Outreach Assets)
  phone_number: originalData.phone_number || scrapedPhones[0] || null,
  linkedin_url: linkedIns[0] || null,
  facebook_url: facebooks[0] || null,
  instagram_url: instagrams[0] || null,

  // Quick status flags
  has_email: (scrapedEmails[0] || originalData.contact_email) !== null,
  has_socials: linkedIns.length > 0 || facebooks.length > 0
};

// Get all items coming directly from the AI output
const inputItems = $input.all();
// Get all items from the original lead payload
const originalLeads = $('Merge Lead Payload').all();

return inputItems.map((item, index) => {
  // Parse AI output string safely
  let aiData = {};
  try {
    aiData = typeof item.json.text === 'string' ? JSON.parse(item.json.text) : item.json;
  } catch (e) {
    aiData = item.json;
  }

  // Safely grab the corresponding lead by index
  const original = originalLeads[index]?.json || {};

  return {
    json: {
      company_name: original.company_name || aiData.company_name || "N/A",
      contact_email: original.contact_email || aiData.contact_email || "N/A",
      lead_score: aiData.lead_score || 0,
      qualification_reason: aiData.qualification_reason || "",
      subject_line: aiData.subject_line || "",
      email_body: aiData.email_body || ""
    }
  };
});
